<script setup lang="ts">import {onMounted,computed} from 'vue';import {useResearch} from '../stores/research';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import SegmentSummary from '../components/SegmentSummary.vue';import RunTable from '../components/RunTable.vue';import {number} from '../utils/format';const store=useResearch(),{error,perform}=useTask();const latest=computed(()=>store.runs.find(r=>r.status==='completed'));const groups=computed(()=>store.segments.filter(s=>s.run_id===latest.value?.id));onMounted(()=>perform(store.load));</script><template><PageHeading eyebrow="FIELD NOTES / RETENTION RESEARCH" title="看见人群的不同节奏" description="把客户特征转化为可解释的研究，再交给真实的运营行动。"><RouterLink class="outline" to="/experiments">发起分群研究 ↗</RouterLink></PageHeading><ErrorNotice :message="error" @retry="perform(store.load)"/><section class="overview-feature"><div class="feature-copy"><p class="eyebrow">本期研究 / 苇岸学习社</p><h2>高价值客户，<br>也可能正在沉默。</h2><p>最近一次学习与消费习惯之间的距离，<br>是本周值得重新观察的线索。</p><RouterLink :to="'/segments?run='+latest?.id">阅读最新群组解释 <span>→</span></RouterLink></div><div class="field-stats"><div><strong>{{number(store.datasets.reduce((n,d)=>n+d.row_count,0))}}</strong><span>匿名学习者 / 已纳入观察</span></div><div class="stat-row"><p><b>{{latest?.result.best_k||'—'}}</b><span>建议群组</span></p><p><b>{{number(latest?.result.silhouette,3)}}</b><span>轮廓系数</span></p></div><small>标准化特征 · 确定性种子 42 · 后端计算</small></div></section><section><div class="section-title"><h2>最新人群笔记 <small>{{latest?.name}}</small></h2><RouterLink to="/segments">查看全部 ↗</RouterLink></div><div class="segment-grid"><SegmentSummary v-for="s in groups" :key="s.id" :segment="s"/></div></section><section class="recent"><div class="section-title"><h2>研究记录 <small>可追溯的每一次尝试</small></h2><RouterLink to="/experiments">全部研究 ↗</RouterLink></div><RunTable :runs="store.runs.slice(0,3)"/></section></template>
